<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick} from 'vue';import {useRoute} from 'vue-router';import {buyer,headers,auth,isDemo,safeUrl} from '../../../shared/api';import {readSse} from '../../../shared/sse';import type {AiMessage,Source,Pet} from '../../../shared/types';import PetCard from '../components/PetCard.vue'
const route=useRoute(),messages=ref<AiMessage[]>([]),input=ref(''),sending=ref(false),error=ref(''),sessionId=ref(''),guest=ref(''),scroller=ref<HTMLElement>(),sessions=ref<{id:string;title?:string}[]>([]);let controller:AbortController|undefined,disposed=false
let pending:{clientMessageId:string;content:string}|null=null
// 游客凭证仅保存在当前标签页，刷新后仍可查看本人的会话历史。
async function credentials(){if(!auth('buyer')&&!guest.value){try{const saved=JSON.parse(sessionStorage.getItem('warmpaw:ai:guest')||'null');if(saved&&Date.parse(saved.expiresAt)>Date.now())guest.value=saved.guestToken}catch{/* 损坏凭证重新申请。 */}if(!guest.value){const result=await buyer<{guestToken:string;expiresAt:string}>('POST','/guest-sessions');guest.value=result.guestToken;sessionStorage.setItem('warmpaw:ai:guest',JSON.stringify(result))}}return {...headers('buyer'),...(guest.value&&!auth('buyer')?{'X-Guest-Token':guest.value}:{})}}
async function ai<T>(path:string,method='GET',body?:unknown):Promise<T>{const res=await fetch('/api/v1'+path,{method,headers:{'Content-Type':'application/json',...await credentials()},body:body?JSON.stringify(body):undefined});const result=await res.json();if(!res.ok)throw new Error(result.message||'会话加载失败');return result.data}
async function openSession(){sessionId.value='';messages.value=[];pending=null;error.value='';try{const s=await ai<{id:string}>('/ai/sessions','POST',route.query.petId?{productId:String(route.query.petId)}:{});sessionId.value=s.id;const list=await ai<{items:{id:string;title?:string}[]}>('/ai/sessions');sessions.value=list.items}catch(e){error.value=e instanceof Error?e.message:'暂时无法创建会话'}}
async function history(){error.value='';try{const all:AiMessage[]=[];let page=1,total=0;do{const result=await ai<{items:AiMessage[];total:number}>(`/ai/sessions/${sessionId.value}/messages?page=${page++}&pageSize=100`);all.push(...result.items);total=result.total}while(all.length<total);messages.value=all;pending=null}catch(e){error.value=String(e)}}
async function bottom(){await nextTick();scroller.value?.scrollTo({top:scroller.value.scrollHeight,behavior:'auto'})}
async function recover(message:AiMessage){for(let i=0;i<15&&!disposed;i++){const saved=await ai<AiMessage>(`/ai/sessions/${sessionId.value}/messages/${message.id}`);Object.assign(message,saved);if(!['generating','streaming','pending'].includes(saved.status))return;await new Promise(resolve=>setTimeout(resolve,2000))}throw new Error('回复仍在处理中，请稍后查看会话历史。')}
async function send(question?:string,retry=false){if(sending.value||!sessionId.value)return;const content=(question??input.value).trim();if(!retry&&!content)return;error.value='';sending.value=true;if(!retry){pending={content,clientMessageId:crypto.randomUUID()};messages.value.push({id:pending.clientMessageId,role:'user',content,status:'completed'});input.value=''}
// 重试复用逻辑消息，移除失败的占位回复，避免重复消息键。
if(retry&&messages.value.at(-1)?.role==='assistant')messages.value.pop();
const current=pending!;const answer=ref<AiMessage>({id:'pending-'+current.clientMessageId,role:'assistant',content:'',status:'generating'});messages.value.push(answer.value);let terminal=false,meta=false;controller=new AbortController();await bottom()
try{const res=await fetch(`/api/v1/ai/sessions/${sessionId.value}/messages`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'text/event-stream',...await credentials()},body:JSON.stringify(current),signal:controller.signal});if(!res.ok){const data=await res.json();throw new Error(data.message||'暂时无法回复')}if(!res.body)throw new Error('回复数据流不可用');await readSse(res.body,(event,data)=>{if(event==='meta'){answer.value.id=String(data.assistantMessageId);meta=true}if(event==='delta')answer.value.content+=String(data.text||'');if(event==='sources')answer.value.sources=data.items as Source[];if(event==='cards'){answer.value.productCards=data.productCards as Pet[];answer.value.orderCards=data.orderCards as AiMessage['orderCards']}if(event==='action')answer.value.actions=data.items as AiMessage['actions'];if(event==='done'){terminal=true;answer.value.status='completed';answer.value.disclaimer=String(data.disclaimer||'AI 生成，仅供参考')}if(event==='error'){terminal=true;answer.value.status='failed';answer.value.actions=data.actions as AiMessage['actions'];error.value=String(data.message);if(data.retryable===false)pending=null}void bottom()});if(!terminal){if(meta)await recover(answer.value);else throw new Error('连接中断，请使用重试继续此问题')}if(answer.value.status==='completed')pending=null
}catch(e){if(disposed)return;if(meta){try{await recover(answer.value);pending=null}catch(recovery){answer.value.status='failed';error.value=recovery instanceof Error?recovery.message:'回复中断'}}else{answer.value.status='failed';error.value=e instanceof Error?e.message:'回复中断'}}finally{sending.value=false;await bottom()}}
async function feedback(message:AiMessage,value:string){try{await ai(`/ai/sessions/${sessionId.value}/messages/${message.id}/feedback`,'PUT',{value});error.value='';message.disclaimer='反馈已收到 · AI 生成，仅供参考'}catch(e){error.value=String(e)}}
onMounted(openSession);onUnmounted(()=>{disposed=true;controller?.abort()})
</script>
<template><div class="container page chat-layout"><aside class="chat-intro"><p class="eyebrow">PAW COMPANION</p><h1>懂一点它，<br>就更靠近一点。</h1><p class="lead">猫狗饲养、健康护理、品种特点，<br>随时聊聊你的疑问。</p><img src="/images/cat.jpg" alt="陪伴在身边的猫咪"><p class="small muted">AI 生成，仅供参考。<br>出现持续不适，请及时就医。</p></aside><section class="chat-panel"><div class="chat-header"><h2>暖爪 AI 助手</h2><button class="text-link" :disabled="sending" @click="openSession">新会话</button></div><select v-if="sessions.length>1" v-model="sessionId" :disabled="sending" aria-label="会话历史" @change="history"><option v-for="(s,index) in sessions" :key="s.id" :value="s.id">{{s.title||`会话 ${index+1}`}}</option></select><p v-if="isDemo" class="notice small">演示回复来自本地示例内容，尚未调用 DeepSeek。</p><div ref="scroller" class="chat-messages" role="log" aria-live="polite"><div v-if="!messages.length" class="welcome-message"><p>你好！我是你的养宠小助手。<br>想了解哪位小伙伴，或聊聊日常照护？</p><button class="suggestion" :disabled="!sessionId" @click="send('幼犬刚到家要注意什么？')">幼犬刚到家要注意什么？ ↗</button><button class="suggestion" :disabled="!sessionId" @click="send('查询我的到店预约')">查询我的到店预约 ↗</button></div><article v-for="message in messages" :key="message.id" class="chat-message" :class="message.role"><small>{{message.role==='user'?'你':'暖爪助手'}}</small><p class="message-content">{{message.content|| (message.status==='generating'?'正在思考…':'暂未收到回答')}}</p><div v-if="message.productCards?.length" class="chat-product-grid"><PetCard v-for="pet in message.productCards" :key="pet.id" :pet="pet"/></div><RouterLink v-for="card in message.orderCards" :key="card.orderId" :to="`/orders/${card.orderId}`" class="suggestion">{{card.orderNo}} · {{card.productName}} · {{card.nextAction}} →</RouterLink><div v-for="action in message.actions" :key="action.type+(action.targetId||'')"><RouterLink v-if="action.type==='login'" class="text-link" to="/login?redirect=/ai">登录后查看本人订单 →</RouterLink><RouterLink v-else-if="action.type==='book_appointment'&&action.targetId" class="text-link" :to="`/checkout/${encodeURIComponent(action.targetId)}`">{{action.label}} →</RouterLink><RouterLink v-else-if="action.type==='view_products'" class="text-link" to="/pets">查看在售宠物 →</RouterLink><RouterLink v-else-if="action.type==='contact_shop'" class="text-link" to="/shop">联系店主 →</RouterLink></div><details v-if="message.sources?.length" class="sources"><summary>参考来源 · {{message.sources.length}}</summary><p v-for="source in message.sources" :key="source.title"><a v-if="source.sourceUrl" :href="safeUrl(source.sourceUrl)" target="_blank" rel="noopener noreferrer">{{source.title}}</a><strong v-else>{{source.title}}</strong><br>{{source.sourceName}} · {{source.excerpt}}</p></details><small v-if="message.role==='assistant'">{{message.disclaimer||'AI 生成，仅供参考'}}</small><div v-if="message.role==='assistant'&&message.status==='completed'" class="actions"><button class="text-link" @click="feedback(message,'up')">有帮助</button><button class="text-link" @click="feedback(message,'down')">未解决</button><RouterLink to="/shop" class="text-link">联系店主</RouterLink></div></article></div><p v-if="error" class="error-text" role="alert">{{error}} <button v-if="pending&&!sending" class="text-link" @click="send(undefined,true)">重试本次问题</button></p><form class="chat-compose" @submit.prevent="send()"><textarea v-model="input" aria-label="输入问题" rows="2" maxlength="2000" placeholder="输入你想了解的内容…" @keydown.enter.exact.prevent="send()"></textarea><button class="btn" :disabled="sending||!input.trim()||!sessionId">{{sending?'回复中…':'发送 →'}}</button></form></section></div></template>
